function card(cls,title,badge,id,body){return `<article class="panel v6-card ${cls}" id="${id}"><div class="v6-card-head"><h3>${title}</h3><span class="badge">${badge}</span></div>${body||'<div class="v6-note">—</div>'}</article>`}
function openV6(){
 $$('.tab').forEach(x=>x.classList.remove('active'));$$('.tabpage').forEach(x=>x.classList.remove('active'));
 $('#v6TabBtn')?.classList.add('active');$('#tab-v6')?.classList.add('active');
}
function openTab(name){const b=$(`[data-tab="${name}"]`);if(b){b.click();return}$$('.tab').forEach(x=>x.classList.remove('active'));$$('.tabpage').forEach(x=>x.classList.remove('active'));$(`#tab-${name}`)?.classList.add('active')}
