function scores(){const rr=text('#rrBadge').match(/1\s*:\s*(\d+(?:\.\d+)?)/);return{technical:numberText('#technicalScore')??50,entry:numberText('#entryScore')??50,rrScore:numberText('#rrScore')??50,fundamental:numberText('#fundScore')??50,confidence:numberText('#confidence')??50,rr:rr?+rr[1]:1,action:text('#actionPill')||'WAIT',price:numberText('#lastPrice')??State.quote?.price??null,invalid:text('#invalidation')||'—',quickSize:text('#quickSize')||'—',wait:text('#waitFor')||'—'}}
function emaSeries(a,p){const out=Array(a.length).fill(null);if(a.length<p)return out;let v=a.slice(0,p).reduce((x,y)=>x+y,0)/p;out[p-1]=v;const k=2/(p+1);for(let i=p;i<a.length;i++){v=a[i]*k+v*(1-k);out[i]=v}return out}
function rsiSeries(a,p=14){const out=Array(a.length).fill(null);if(a.length<=p)return out;let g=0,l=0;for(let i=1;i<=p;i++){const d=a[i]-a[i-1];g+=Math.max(0,d);l+=Math.max(0,-d)}g/=p;l/=p;out[p]=l?100-100/(1+g/l):100;for(let i=p+1;i<a.length;i++){const d=a[i]-a[i-1];g=(g*(p-1)+Math.max(0,d))/p;l=(l*(p-1)+Math.max(0,-d))/p;out[i]=l?100-100/(1+g/l):100}return out}
function atrSeries(bs,p=14){const tr=bs.map((b,i)=>i?Math.max(b.high-b.low,Math.abs(b.high-bs[i-1].close),Math.abs(b.low-bs[i-1].close)):b.high-b.low),out=Array(bs.length).fill(null);if(tr.length<p+1)return out;let v=tr.slice(1,p+1).reduce((a,b)=>a+b,0)/p;out[p]=v;for(let i=p+1;i<tr.length;i++){v=(v*(p-1)+tr[i])/p;out[i]=v}return out}
function dailyContext(){const b=State.daily?.bars||[],c=b.map(x=>x.close),e20=emaSeries(c,20),e50=emaSeries(c,50),e200=emaSeries(c,200),r=rsiSeries(c),a=atrSeries(b),i=b.length-1;return{bars:b,close:c[i],e20:e20[i],e50:e50[i],e200:e200[i],rsi:r[i],atr:a[i],trend:Number.isFinite(e20[i])&&Number.isFinite(e50[i])&&c[i]>e20[i]&&e20[i]>e50[i],longTrend:Number.isFinite(e200[i])?c[i]>e200[i]:null}}
function strategy(){const s=scores(),d=dailyContext(),i=State.intraday||{},p=$('#v6Profile')?.value||'swing',reasons=[],good=[];let selected='WAIT / CONFIRM';if(p==='day'){selected=i.session==='REGULAR'&&Number.isFinite(i.rvol)&&i.rvol>=1.2&&i.regular?.vwap&&i.price>i.regular.vwap?'VWAP / OPENING RANGE':'WAIT FOR VOLUME / STRUCTURE'}else if(p==='swing')selected=d.trend?'PULLBACK / TREND FOLLOWING':'WAIT / MEAN REVERSION';else if(p==='position')selected=d.trend&&d.longTrend?'TREND + QUALITY':'SELECTIVE / WAIT';else selected=s.fundamental>=65&&d.longTrend!==false?'QUALITY / LONG-TERM':'WATCHLIST ONLY';if(s.rr<1.2)reasons.push('R:R < 1.2');if(s.entry<42)reasons.push('Entry quality < 42');if(s.technical<42)reasons.push('Technical < 42');if(p==='day'&&Number.isFinite(i.rvol)&&i.rvol<.65)reasons.push('RVOL < 0.65');if(p==='day'&&Number.isFinite(i.gapAtr)&&Math.abs(i.gapAtr)>2)reasons.push('|Gap| > 2 ATR');if(d.trend)good.push('trend aligned');if(Number.isFinite(d.rsi))good.push(`RSI ${d.rsi.toFixed(0)}`);if(Number.isFinite(i.rvol))good.push(`RVOL ${i.rvol.toFixed(2)}×`);if(i.regular?.vwap&&i.price)good.push(i.price>i.regular.vwap?'above VWAP':'below VWAP');return{profile:p,selected,noTrade:reasons.length>0,reasons,good,d,s}}

function renderHero(){const s=scores(),g=strategy(),q=State.quote,i=State.intraday,hold=holdingFor(symbol());const feed=q?feedStatus(q):'—';$('#v6HeroTitle').textContent=`${symbol()} · ${q?.price?usd(q.price):'—'}`;$('#v6HeroSub').textContent=g.noTrade?`${L('งดเทรด','NO TRADE')}: ${g.reasons.join(' · ')}`:`${g.selected} · ${g.good.join(' · ')||L('รอหลักฐานเพิ่ม','waiting for more evidence')}`;$('#v6Provider').textContent=`${q?.provider||'—'} · ${feed}`;$('#v6Provider').className=`v6-chip ${q?.realTime?'good':q?.error?'bad':'warn'}`;$('#v6Session').textContent=i?.session||q?.session||'—';$('#v6RefreshStamp').textContent=State.lastRefresh?new Date(State.lastRefresh).toLocaleTimeString(isTh()?'th-TH':'en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';$('#v6Action').textContent=g.noTrade?'NO TRADE':g.selected;$('#v6Action').className=g.noTrade?'v6-bad':'v6-good';$('#v6ActionWhy').textContent=(g.noTrade?g.reasons:g.good).join(' · ')||'—';$('#v6Entry').textContent=i?.session==='REGULAR'&&i.openingRange?.m15?.high?`OR15 ${usd(i.openingRange.m15.high)}`:s.wait;$('#v6Wait').textContent=i?.playbook?.[0]||s.wait;$('#v6Risk').textContent=s.invalid;$('#v6RR').textContent=`R:R ${Number.isFinite(s.rr)?`1:${s.rr.toFixed(2)}`:'—'} · ATR ${fmt(g.d.atr)}`;$('#v6Size').textContent=s.quickSize;$('#v6Holding').textContent=hold?`${hold.shares||0} sh · avg ${usd(hold.avgUsd||hold.avg||hold.cost)}`:L('ยังไม่มีหุ้นนี้ในพอร์ต','No current holding for this symbol')}
function feedStatus(q){if((q.session||'').includes('CLOSED'))return'MARKET CLOSED';return q.realTime?'REAL-TIME':'PUBLIC-MAY-BE-DELAYED'}
function renderFeed(){const q=State.quote,el=$('#v6Feed');if(!q){el.innerHTML='<div class="v6-note">Feed unavailable</div>';return}el.innerHTML=`<div class="v6-kpis"><div class="v6-kpi"><span>Provider</span><b>${esc(q.provider)}</b></div><div class="v6-kpi"><span>Status</span><b class="${q.realTime?'v6-good':'v6-warn'}">${esc(feedStatus(q))}</b></div><div class="v6-kpi"><span>Last</span><b>${usd(q.price)}</b></div><div class="v6-kpi"><span>Session</span><b>${esc(q.session)}</b></div></div><div class="v6-note">${q.timestamp?new Date(q.timestamp).toLocaleString(isTh()?'th-TH':'en-US'):''}${q.bid?` · Bid ${usd(q.bid)}`:''}${q.ask?` · Ask ${usd(q.ask)}`:''}</div>`}
function renderBreadth(){const b=State.breadth,el=$('#v6Breadth');if(!b){el.innerHTML='<div class="v6-note">Breadth unavailable</div>';return}el.innerHTML=`<div class="v6-kpis">${[['Adv / Dec',`${b.advance} / ${b.decline}`],['A/D',fmt(b.advanceDeclineRatio)],['> EMA20',`${b.aboveEMA20}%`],['> EMA50',`${b.aboveEMA50}%`],['> EMA200',`${b.aboveEMA200}%`],['20D H/L',`${b.newHigh20} / ${b.newLow20}`],['Avg',pct(b.averageChange)],['Coverage',`${b.coverage}/${b.total}`]].map(x=>`<div class="v6-kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="v6-note">Representative liquid US basket — not full NYSE/Nasdaq breadth.</div>`}
function renderIntraday(){const x=State.intraday,el=$('#v6Intraday');if(!x||x.error){el.innerHTML=`<div class="v6-note">${esc(x?.error||'Intraday unavailable')}</div>`;return}const rows=[['Feed time',x.lastBarEt],['Gap',pct(x.gapPct)],['Gap / ATR',Number.isFinite(x.gapAtr)?`${x.gapAtr.toFixed(2)} ATR`:'—'],['PM H / L',x.premarket?.high?`${usd(x.premarket.high)} / ${usd(x.premarket.low)}`:'—'],['OR 5m',x.openingRange?.m5?.high?`${usd(x.openingRange.m5.high)} / ${usd(x.openingRange.m5.low)}`:'—'],['OR 15m',x.openingRange?.m15?.high?`${usd(x.openingRange.m15.high)} / ${usd(x.openingRange.m15.low)}`:'—'],['OR 30m',x.openingRange?.m30?.high?`${usd(x.openingRange.m30.high)} / ${usd(x.openingRange.m30.low)}`:'—'],['VWAP',usd(x.regular?.vwap)],['Prev Day H/L',x.previousDay?.high?`${usd(x.previousDay.high)} / ${usd(x.previousDay.low)}`:'—'],['RVOL',Number.isFinite(x.rvol)?`${x.rvol.toFixed(2)}× (n=${x.rvolSample})`:'—'],['Volume z',Number.isFinite(x.volumeZ)?x.volumeZ.toFixed(2):'—'],['Flow',x.flow||'—']];el.innerHTML=`<div class="v6-list">${rows.map(r=>`<div class="v6-row"><span>${esc(r[0])}</span><b>${esc(r[1])}</b></div>`).join('')}</div><div class="v6-note">${(x.playbook||[]).map(esc).join('<br>')}</div>`}
function renderStrategy(){const g=strategy(),el=$('#v6StrategyBody');el.innerHTML=`<div class="v6-kpi"><span>${g.noTrade?'Gate':'Selected strategy'}</span><b class="${g.noTrade?'v6-bad':'v6-good'}">${g.noTrade?'NO TRADE — EDGE INSUFFICIENT':esc(g.selected)}</b></div><div class="v6-note">${esc((g.noTrade?g.reasons:g.good).join(' · ')||'Waiting for evidence')}</div>`}
function scenario(){const s=scores(),i=State.intraday||{};let a=30+(s.technical-50)*.35+(s.entry-50)*.22+(s.rrScore-50)*.12+(Number.isFinite(i.rvol)?Math.min(12,(i.rvol-1)*8):0),b=38-Math.abs(s.technical-55)*.15,c=30+(50-s.technical)*.25+(50-s.entry)*.12;a=Math.max(5,a);b=Math.max(8,b);c=Math.max(5,c);const z=a+b+c;return[['Breakout continuation',a/z*100],['Pullback holds',b/z*100],['Breakdown',c/z*100]]}
function renderScenario(){const el=$('#v6ScenarioBody');el.innerHTML=scenario().map(x=>`<div class="v6-bar"><span>${x[0]}</span><i><em style="width:${x[1]}%"></em></i><b>${x[1].toFixed(0)}%</b></div>`).join('')}
function renderQuality(){const s=scores(),tim=(s.technical+s.entry)/2;let q='Avoid / Wait',cls='v6-bad';if(s.fundamental>=65&&tim>=65){q='High Quality + Good Entry';cls='v6-good'}else if(s.fundamental>=65){q='High Quality + Bad Entry';cls='v6-warn'}else if(tim>=65){q='Lower Quality + Technical Bounce';cls='v6-warn'}$('#v6Quality').innerHTML=`<div class="v6-kpi"><span>Quadrant</span><b class="${cls}">${q}</b></div><div class="v6-kpis" style="margin-top:7px"><div class="v6-kpi"><span>Quality</span><b>${s.fundamental.toFixed(0)}</b></div><div class="v6-kpi"><span>Timing</span><b>${tim.toFixed(0)}</b></div></div>`}

function evalSetup(bs,fast=20){const c=bs.map(x=>x.close),ef=emaSeries(c,fast),e50=emaSeries(c,50),rv=rsiSeries(c),av=atrSeries(bs),tr=[];for(let i=55;i<bs.length-11;i++){if(!(c[i]>ef[i]&&ef[i]>e50[i]&&rv[i]>=48&&rv[i]<=68&&av[i]>0))continue;const entry=c[i],stop=entry-1.5*av[i],tp=entry+2*av[i];let ret=null;for(let j=i+1;j<=i+10;j++){if(bs[j].low<=stop){ret=stop/entry-1;break}if(bs[j].high>=tp){ret=tp/entry-1;break}}if(ret!=null){tr.push({i,ret});i+=3}}return tr}
function tstats(t){if(!t.length)return{n:0,wr:null,pf:null};const w=t.filter(x=>x.ret>0),l=t.filter(x=>x.ret<=0),gp=w.reduce((a,x)=>a+x.ret,0),gl=Math.abs(l.reduce((a,x)=>a+x.ret,0));return{n:t.length,wr:w.length/t.length*100,pf:gl?gp/gl:(gp?99:null)}}
function renderReliability(){const bs=State.daily?.bars||[],el=$('#v6Reliability');if(bs.length<120){el.innerHTML='<div class="v6-note">Insufficient daily history.</div>';return}const cut=Math.floor(bs.length*.7),all=evalSetup(bs,20),tr=tstats(all.filter(x=>x.i<cut)),oo=tstats(all.filter(x=>x.i>=cut));el.innerHTML=`<div class="v6-list">${[['Samples',all.length],['Train WR',tr.wr==null?'—':`${tr.wr.toFixed(0)}%`],['OOS WR',oo.wr==null?'—':`${oo.wr.toFixed(0)}%`],['OOS PF',oo.pf==null?'—':oo.pf.toFixed(2)],['Status',oo.n<8?'LOW SAMPLE':oo.wr>=55&&oo.pf>=1.2?'REASONABLY STABLE':'UNSTABLE OOS']].map(x=>`<div class="v6-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="v6-note">Chronological 70/30 split; not rolling walk-forward optimization.</div>`}
function renderRobust(){const bs=State.daily?.bars||[],el=$('#v6RobustBody');if(bs.length<120){el.textContent='—';return}const cut=Math.floor(bs.length*.7);el.innerHTML=[15,18,20,22,25].map(p=>{const s=tstats(evalSetup(bs,p).filter(x=>x.i>=cut));return `<div class="v6-cell"><span>EMA ${p}</span><b>${s.wr==null?'—':s.wr.toFixed(0)+'%'}</b><span>n=${s.n} · PF ${s.pf==null?'—':s.pf.toFixed(1)}</span></div>`}).join('')}
function renderMonte(){const bs=State.daily?.bars||[],c=bs.map(x=>x.close),r=[];for(let i=Math.max(1,c.length-252);i<c.length;i++)r.push(c[i]/c[i-1]-1);const el=$('#v6Monte');if(r.length<30){el.innerHTML='<div class="v6-note">Insufficient return history.</div>';return}const N=2000,out=[];for(let p=0;p<N;p++){let v=1;for(let d=0;d<20;d++)v*=1+r[Math.floor(Math.random()*r.length)];out.push((v-1)*100)}out.sort((a,b)=>a-b);const q=f=>out[Math.floor((out.length-1)*f)],loss=out.filter(x=>x<0).length/N*100;el.innerHTML=`<div class="v6-list">${[['Paths',N],['5th percentile',pct(q(.05))],['Median',pct(q(.5))],['95th percentile',pct(q(.95))],['P(return < 0)',`${loss.toFixed(0)}%`]].map(x=>`<div class="v6-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="v6-note">Historical bootstrap risk distribution, not a price forecast.</div>`}

function renderCost(){const q=State.quote,s=scores(),avg=+($('#v6AvgCost')?.value||0),shares=+($('#v6Shares')?.value||0),price=q?.price||s.price,stop=numberText('#invalidation'),gain=avg>0&&price?(price/avg-1)*100:null,value=shares&&price?shares*price:null,dist=price&&stop?(price-stop)/price*100:null;$('#v6CostBody').innerHTML=[['Gain vs cost',gain==null?'—':pct(gain)],['Position value',value==null?'—':usd(value)],['Distance to stop',dist==null?'—':pct(dist)],['Unrealized P&L',avg&&shares&&price?usd((price-avg)*shares):'—']].map(x=>`<div class="v6-kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
